import{_ as t,o,c as n,ah as r}from"./chunks/framework.BsNNkeaH.js";const d=JSON.parse('{"title":"Report cards and lesson log","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/enseignant/bulletins-et-cahier-texte.md","filePath":"src/en/guide/enseignant/bulletins-et-cahier-texte.md"}'),a={name:"en/guide/enseignant/bulletins-et-cahier-texte.md"};function s(i,e,l,c,h,g){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="report-cards-and-lesson-log" tabindex="-1">Report cards and lesson log <a class="header-anchor" href="#report-cards-and-lesson-log" aria-label="Permalink to &quot;Report cards and lesson log&quot;">​</a></h1><p>This page covers two distinct tasks: writing the appreciations that will appear on your students&#39; report cards, and keeping the lesson log that tracks what was covered in your sessions and the homework assigned.</p><h2 id="write-per-subject-appreciations" tabindex="-1">Write per-subject appreciations <a class="header-anchor" href="#write-per-subject-appreciations" aria-label="Permalink to &quot;Write per-subject appreciations&quot;">​</a></h2><p>For each of your class/subject assignments, you can enter one appreciation per student for a given academic period.</p><ol><li>From the <strong>Evaluations</strong> list, click <strong>Bulletins</strong> on the row of an evaluation for the relevant class and subject.</li><li>Choose the <strong>academic period</strong> from the selector at the top of the page.</li><li>For each student, enter their <strong>Appreciation</strong> in the text field (optional).</li><li>Click <strong>Save</strong> — every appreciation in the list is saved at once.</li></ol><h2 id="write-the-end-of-period-general-appreciation-homeroom-teacher" tabindex="-1">Write the end-of-period general appreciation (homeroom teacher) <a class="header-anchor" href="#write-the-end-of-period-general-appreciation-homeroom-teacher" aria-label="Permalink to &quot;Write the end-of-period general appreciation (homeroom teacher)&quot;">​</a></h2><p>If you are the homeroom teacher of a class, you also enter an end-of-period general appreciation, separate from the per-subject ones.</p><ol><li>Open <strong>Teaching → My homeroom class</strong>, then click <strong>End-of-period appreciations</strong> next to the relevant class.</li><li>Choose the <strong>academic period</strong> from the selector at the top of the page.</li><li>For each student, fill in the <strong>General appreciation</strong> and <strong>Conduct</strong> fields, and check any relevant flags: <strong>Congratulations</strong>, <strong>Compliments</strong>, <strong>Encouragements</strong>, <strong>Work warning</strong>, <strong>Conduct warning</strong>.</li><li>Click <strong>Save</strong>.</li></ol><h2 id="keep-the-lesson-log" tabindex="-1">Keep the lesson log <a class="header-anchor" href="#keep-the-lesson-log" aria-label="Permalink to &quot;Keep the lesson log&quot;">​</a></h2><p>The lesson log tracks, session by session, what was covered in class and the homework assigned, for all your class/subject assignments.</p><ol><li>Open <strong>Teaching → Lesson log</strong>, then click <strong>New entry</strong>.</li><li>Choose the <strong>Class</strong> and <strong>Subject</strong>, then fill in the <strong>Date</strong>.</li><li>Describe the <strong>Content covered</strong> (required) and, if relevant, the <strong>Homework</strong> assigned.</li><li>Optionally attach a <strong>Document</strong> (PDF, JPG or PNG).</li><li>Click <strong>Save</strong>.</li></ol><p>The list of entries can be filtered by keyword (searching the content) or by class, and shows each entry&#39;s date, class, subject, content and homework. From this list:</p><ul><li>the <strong>Document</strong> button downloads the attachment if an entry has one;</li><li><strong>Edit</strong> reopens the entry to correct it (you can replace or remove the attached document there);</li><li><strong>Delete</strong> permanently removes it, after confirmation — this cannot be undone.</li></ul>',13)])])}const u=t(a,[["render",s]]);export{d as __pageData,u as default};
